import { motion } from "framer-motion";

function Skills() {
  const skills = ["Java", "Python", "C/C++", "HTML", "CSS", "Bootstrap", "JavaScript", "SQL", "Excel", "Power BI"];

  return (
    <section id="skills" className="py-20 bg-gray-800 text-center">
      <h2 className="text-3xl font-bold text-purple-400 mb-10">Technical Skills</h2>
      <div className="grid md:grid-cols-3 gap-8 px-6">
        {skills.map((skill, index) => (
          <motion.div
            key={index}
            className="bg-gray-900 p-6 rounded-lg shadow-lg hover:scale-105 transition-transform"
            initial={{ opacity: 0, y: 50 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{
              duration: 0.8,   // kitni der me complete hoga
              delay: index * 0.2, // har skill thoda delay ke sath aayegi
              type: "spring",  // bounce effect ke sath smoothness
            }}
          >
            <p className="text-lg text-gray-300">{skill}</p>
          </motion.div>
        ))}
      </div>
    </section>
  );
}

export default Skills;
